ALTER TABLE users ADD COLUMN display_name VARCHAR(120) NOT NULL DEFAULT '', ADD COLUMN email VARCHAR(160) NOT NULL DEFAULT '', ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, ADD COLUMN last_login_at TIMESTAMP NULL;
ALTER TABLE roles ADD COLUMN built_in BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE permissions ADD COLUMN module VARCHAR(80) NOT NULL DEFAULT 'system';
CREATE TABLE IF NOT EXISTS auth_sessions(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,access_token_hash CHAR(64) NOT NULL UNIQUE,refresh_token_hash CHAR(64) NOT NULL UNIQUE,access_expires_at TIMESTAMP NOT NULL,refresh_expires_at TIMESTAMP NOT NULL,revoked_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,user_agent VARCHAR(255) NOT NULL DEFAULT '',ip_address VARCHAR(64) NOT NULL DEFAULT '',INDEX idx_session_user(user_id,revoked_at),INDEX idx_session_access(access_token_hash),INDEX idx_session_refresh(refresh_token_hash));
